# Act 1: corridor, checkpoint, medical deck.

IONA_MEET = {
    "id": "iona_meet",
    "entry": [{"node": "start"}],
    "nodes": {
        "start": N("iona", "Pickets down. You fight like Lattice: you watch the room before you watch the target. Officer Iona Rell, ship's security. Who are you?",
            C("{name}. Former operator. Right now, a passenger.", "who_plain"),
            C("Lattice Corps, operator first class. Discharged.", "who_vet", cond=[{"background": "veteran"}], tag="Veteran", effects=[inf("iona", 2, "meet_vet", "Gave her a straight service record")]),
            C("Does it matter? You're alive.", "who_hard", tone="hard", effects=[inf("iona", -1, "meet_dodge", "Dodged her question")])),
        "who_plain": N("iona", "A passenger with a Lumen Edge. All right, passenger. Here's the situation.", nxt="situation"),
        "who_vet": N("iona", "First class. Then you know how a lattice goes wrong. Here's the situation.", nxt="situation"),
        "who_hard": N("iona", "It matters to my report, if anyone ever reads it. Fine. Here's the situation.", nxt="situation"),
        "situation": N("iona", "The WARDEN went to Archive Protection twenty minutes ago. The commander set its priorities before we left orbit: archive first, command second, crew third. Passengers didn't make the list. Lantern reclaimers cut in through the dorsal hull over the hold. Launch craft Petrel is in Bay 2, all the way forward: checkpoint, medical, engineering, archive hold, command, bay.",
            C("Then we go forward and we bring everyone we can on the way.", "r_comp", tone="compassionate", effects=[inf("iona", 5, "meet_everyone", "Wants to bring everyone"), align(3, "meet_everyone", "Resolved to save everyone they can")]),
            C("We move fast. We can't stop for every door.", "r_prag", tone="pragmatic", effects=[inf("iona", 1, "meet_fast", "Kept a clear head")]),
            C("I'm getting on that craft. You can come with me.", "r_self", tone="self-interested", effects=[inf("iona", -3, "meet_self", "Only thinking of themself")]),
            C("Why would anyone set a ship to guard cargo over people?", "r_skep", tone="skeptical", effects=[inf("iona", 2, "meet_why", "Questioned the commander's priorities")]),
            C("Follow my lead and we both live.", "r_hard", tone="hard", effects=[inf("iona", -2, "meet_orders", "Tried to give her orders")])),
        "r_comp": N("iona", "Everyone we can. That's the job, isn't it. That's the only version of the job I can live with.", nxt="medpac"),
        "r_prag": N("iona", "Fast saves people too. Fine. But I'll stop for the ones who can't run.", nxt="medpac"),
        "r_self": N("iona", "Generous. I'm not leaving my post just to buy you a seat, but our routes match. For now.", nxt="medpac"),
        "r_hard": N("iona", "I don't take orders from passengers. I'll take good ideas. You've had one so far: shooting the drones.", nxt="medpac"),
        "r_skep": N("iona", "Because the commander says what's in that hold matters more than all of us. Maybe it does. She also had me seal the passenger ward on the medical deck two hours ago, with five people inside. I did it. I'm telling you because you're going to see that door.", nxt="medpac", effects=[flag("iona_told_ward")]),
        "medpac": N("iona", "Here. Field medpac. Use it, don't hoard it. It takes a moment to apply, so you can't slap three on in one breath, and nobody can. And take my keycard. The armory locker at the checkpoint is mechanical; the WARDEN can't lock that one.",
            effects=[{"give_item": "medpac", "count": 1, "key": "iona_medpac"}, {"give_item": "iona_keycard", "count": 1, "key": "iona_keycard"}, {"tutorial": "healing"}, {"tutorial": "queue"}],
            *[C("Thanks, Iona. Let's move.", "end_node"),
              C("You're trusting a stranger with your keycard?", "trust")]),
        "trust": N("iona", "I'm trusting the stranger who just saved my life. Don't make me revise that.", nxt="end_node", effects=[inf("iona", 1, "meet_trust", "Asked why she trusted them")]),
        "end_node": N("iona", "Checkpoint's through that door. WARDEN put a turret and pickets on it. I'd rather not walk into its guns, if you have a better idea.", effects=[xp(100, "iona_meet", "Joined forces with Iona Rell")], end=True),
    },
}

