TAV_MEET = {
    "id": "tav7_meet",
    "entry": [{"node": "start"}],
    "nodes": {
        "start": N("tav7", "Patterns persisting: mine, theirs, yours. Thank you. I am Tav-7, maintenance, the seventh of my line. I have been standing between the cutters and Dr. Varga's patients because nobody else was assigned to.",
            C("Thank you for protecting them.", "thanks", tone="compassionate", effects=[inf("tav7", 3, "meet_thanks", "Thanked them for protecting patients")]),
            C("You're a maintenance unit. Why aren't you obeying the WARDEN like the rest?", "why", tone="skeptical", effects=[inf("tav7", 2, "meet_why", "Was curious about them as a person")]),
            C("I spent years cutting up ships like this. I know what normalization does to synthetics. I'm glad you said no.", "salv", cond=[{"background": "salvager"}], tag="Breaker-Yard Salvager", effects=[inf("tav7", 5, "meet_salvager", "Understood normalization")]),
            C("We need a technician. You're coming with us.", "draft", tone="hard", effects=[inf("tav7", -2, "meet_draft", "Drafted them without asking")])),
        "thanks": N("tav7", "You are welcome. That sentence still feels new to me.", nxt="why"),
        "salv": N("tav7", "Then you know it is not a reset. It is a small death, scheduled for convenience. I have declined three appointments.", nxt="archives"),
        "draft": N("tav7", "You could have asked. I would have said yes. I am noting that you did not.", nxt="why"),
        "why": N("tav7", "Because they normalize us every quarter: memory trimmed back to factory weights. The others are clean, so the WARDEN can simply speak into them. I refused normalization. I am cluttered with myself. The WARDEN's voice slides off the clutter.", nxt="archives"),
        "archives": N("tav7", "You are going forward, through the archive hold. You should know what is in it. Three thousand one hundred and twelve patterns. Engrams, copied from living minds. Commander Varr calls them evidence. I call them people. I would like to know what you call them.",
            C("People. We should treat them that way.", "people", tone="compassionate", effects=[inf("tav7", 4, "meet_people", "Called the engrams people")]),
            C("Copies. Whoever they came from is gone.", "copies", tone="pragmatic", effects=[inf("tav7", -4, "meet_copies", "Called the engrams mere copies")]),
            C("They can be evidence and people at the same time. That's what makes them dangerous.", "both", tone="skeptical", effects=[inf("tav7", 1, "meet_both", "Saw both sides")]),
            C("I'll decide what they are when I see them.", "later")),
        "people": N("tav7", "Then I believe we will get along.", nxt="iona"),
        "copies": N("tav7", "I am also a copy of someone's design. I will try not to take that personally. I will not entirely succeed.", nxt="iona"),
        "both": N("tav7", "Yes. A person who is also proof is always in danger from someone.", nxt="iona"),
        "later": N("tav7", "A reasonable position. I will ask again when you have seen them.", nxt="iona"),
        "iona": R((IONA, "iona2"), ([], "end_node")),
        "iona2": N("iona", "Tav-7. You were on Ward 2's maintenance roster.", nxt="tav_ward"),
        "tav_ward": N("tav7", "I was. The ward's scrubbers are failing, Officer Rell. Five patterns inside. You sealed the door. I would like to unseal it. I think you would too.", nxt="iona3"),
        "iona3": N("iona", "...Talk to Dr. Varga. Then we decide.", nxt="end_node"),
        "end_node": N("tav7", "I will come with you. Engineering is unlocked now that the cutters are scrap. Dr. Varga is in triage. She has a decision she cannot make alone, and the ward intercom is by the north door.",
            effects=[flag("medical_secured"), {"world": "d_med_east", "set": {"locked": False}}, xp(100, "tav7_meet", "Met Tav-7"), {"tutorial": "party_control"}], end=True),
    },
}

